// resolversForDescendingHistory builds resolvers when "history" is in descending order
// (e.g. 5, 4, 3, 2, 1), looking ahead for each item's "previousSiteConfig".
func (s *SiteConfigurationChangeConnectionStore) resolversForDescendingHistory(history []*database.SiteConfig) []*SiteConfigurationChangeResolver {
	resolvers := make([]*SiteConfigurationChangeResolver, 0, len(history))
	for i := 0; i < len(history); i++ {
		var previousSiteConfig *database.SiteConfig
		if i != len(history)-1 {
			previousSiteConfig = history[i+1]
		}

		resolvers = append(resolvers, &SiteConfigurationChangeResolver{
			db:                 s.db,
			siteConfig:         history[i],
			previousSiteConfig: previousSiteConfig,
		})
	}

	return resolvers
}

// resolversForAscendingHistory builds resolvers when "history" is in ascending order
// (e.g. 1, 2, 3, 4, 5), looking behind for each item's "previousSiteConfig".
func (s *SiteConfigurationChangeConnectionStore) resolversForAscendingHistory(history []*database.SiteConfig) []*SiteConfigurationChangeResolver {
	resolvers := make([]*SiteConfigurationChangeResolver, 0, len(history))
	for i := 0; i < len(history); i++ {
		var previousSiteConfig *database.SiteConfig
		if i > 0 {
			previousSiteConfig = history[i-1]
		}

		resolvers = append(resolvers, &SiteConfigurationChangeResolver{
			db:                 s.db,
			siteConfig:         history[i],
			previousSiteConfig: previousSiteConfig,
		})
	}

	return resolvers
}

